\mathrm{df\text{-}range\text{-}principles}\vdash\;\begin{aligned}
\mathsf{Range}(f,X)&\leftrightarrow\mathsf{Fun}(f,N,N)\land\forall n(n\in X\leftrightarrow\exists m\;\langle m,n\rangle_N\in f),\\
\mathrm{IR}&\coloneqq\forall f(\mathsf{Inj}(f,N,N)\to\exists X\;\mathsf{Range}(f,X)),\\
\mathrm{FR}&\coloneqq\forall f(\mathsf{Fun}(f,N,N)\to\exists X\;\mathsf{Range}(f,X)).
\end{aligned}
